<?php
require_once __DIR__.'/../config.php'; require_once __DIR__.'/../includes/functions.php'; $pageTitle='Enter Results'; require_role(['teacher']); require_once __DIR__.'/../includes/header.php';$q=$pdo->prepare('SELECT id FROM teachers WHERE user_id=?');$q->execute([user()['id']]);$tid=(int)$q->fetchColumn();$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$student=(int)$_POST['student_id'];$subject=(int)$_POST['subject_id'];$term=(int)$_POST['term_id'];$ca=(float)$_POST['ca'];$exam=(float)$_POST['exam'];$st=$pdo->prepare('SELECT s.class_id FROM students s WHERE s.id=? AND s.status="active"');$st->execute([$student]);$classId=$st->fetchColumn();$sub=$pdo->prepare('SELECT max_ca,max_exam FROM subjects WHERE id=? AND active=1');$sub->execute([$subject]);$limits=$sub->fetch();if(!$classId||!$limits)throw new RuntimeException('Invalid student or subject.');if(!user_has_teacher_class($pdo,$tid,(int)$classId)||!user_has_teacher_subject($pdo,$tid,$subject))throw new RuntimeException('You are not assigned to this class/subject.');if($ca<0||$ca>(float)$limits['max_ca']||$exam<0||$exam>(float)$limits['max_exam'])throw new RuntimeException('Scores exceed the configured subject maximum.');[$g,$r]=grade($ca+$exam);$st=$pdo->prepare("INSERT INTO results(student_id,subject_id,term_id,ca_score,exam_score,grade,remarks,entered_by) VALUES(?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE ca_score=VALUES(ca_score),exam_score=VALUES(exam_score),grade=VALUES(grade),remarks=VALUES(remarks),entered_by=VALUES(entered_by)");$st->execute([$student,$subject,$term,$ca,$exam,$g,$r,user()['id']]);audit($pdo,'save','results',null,'Teacher result entry');flash('success','Result saved.');redirect('results.php');}catch(Throwable $e){$error=$e->getMessage();}}
$students=$pdo->prepare("SELECT s.id,s.admission_no,s.surname,s.firstname FROM students s WHERE s.status='active' AND EXISTS(SELECT 1 FROM teacher_classes tc WHERE tc.teacher_id=? AND tc.class_id=s.class_id) ORDER BY s.surname,s.firstname");$students->execute([$tid]);$students=$students->fetchAll();$subjects=$pdo->prepare("SELECT sub.* FROM subjects sub JOIN teacher_subjects ts ON ts.subject_id=sub.id WHERE ts.teacher_id=? AND sub.active=1 ORDER BY sub.subject_name");$subjects->execute([$tid]);$subjects=$subjects->fetchAll();$terms=$pdo->query("SELECT * FROM academic_terms ORDER BY is_current DESC,id DESC")->fetchAll();$rows=$pdo->prepare("SELECT r.*,s.admission_no,CONCAT(s.surname,' ',s.firstname) student,sub.subject_name,t.term_name,t.session_name FROM results r JOIN students s ON s.id=r.student_id JOIN subjects sub ON sub.id=r.subject_id JOIN academic_terms t ON t.id=r.term_id JOIN teacher_classes tc ON tc.class_id=s.class_id WHERE tc.teacher_id=? ORDER BY r.id DESC LIMIT 100");$rows->execute([$tid]);$rows=$rows->fetchAll();$success=flash('success');
?><h2>Enter Results</h2><?php if($success): ?><div class="alert alert-success"><?=e($success)?></div><?php endif;?><?php if($error): ?><div class="alert alert-danger"><?=e($error)?></div><?php endif;?><div class="card p-4 mb-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-4"><label>Student</label><select class="form-select" name="student_id" required><option value="">Select</option><?php foreach($students as $s): ?><option value="<?=$s['id']?>"><?=e($s['admission_no'].' — '.$s['surname'].' '.$s['firstname'])?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Subject</label><select class="form-select" name="subject_id" required><?php foreach($subjects as $s): ?><option value="<?=$s['id']?>" data-ca="<?=$s['max_ca']?>" data-exam="<?=$s['max_exam']?>"><?=e($s['subject_name'].' (CA '.$s['max_ca'].' / Exam '.$s['max_exam'].')')?></option><?php endforeach;?></select></div><div class="col-md-3"><label>Term</label><select class="form-select" name="term_id" required><?php foreach($terms as $t): ?><option value="<?=$t['id']?>"><?=e($t['session_name'].' — '.$t['term_name'])?></option><?php endforeach;?></select></div><div class="col-md-1"><label>CA</label><input class="form-control" type="number" min="0" step=".01" name="ca" required></div><div class="col-md-1"><label>Exam</label><input class="form-control" type="number" min="0" step=".01" name="exam" required></div><div class="col-12"><button class="btn btn-primary">Save result</button></div></form></div><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Student</th><th>Subject</th><th>Term</th><th>Total</th><th>Grade</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['student'])?></td><td><?=e($r['subject_name'])?></td><td><?=e($r['session_name'].' '.$r['term_name'])?></td><td><?=$r['total']?></td><td><?=e($r['grade'])?></td></tr><?php endforeach;?></tbody></table></div><?php require __DIR__.'/../includes/footer.php';
